import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import Navbar from './components/Navbar';
import Footer from './components/Footer';
import CartDrawer from './components/CartDrawer';
import Home from './pages/Home';
import Category from './pages/Category';
import Checkout from './pages/Checkout';
import Dashboard from './pages/Dashboard';
import './App.css';

function App() {
  const [cartItems, setCartItems] = useState([]);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [user, setUser] = useState(null);
  const [token, setToken] = useState(localStorage.getItem('token') || null);

  useEffect(() => {
    const savedCart = localStorage.getItem('cart');
    if (savedCart) {
      try { setCartItems(JSON.parse(savedCart)); } catch(e) {}
      setCartItems(JSON.parse(savedCart));
    }
    // Load user from localStorage
    const savedUser = localStorage.getItem('user');
    if (savedUser) {
      setUser(JSON.parse(savedUser));
    }
  }, []);

  useEffect(() => {
    // Save cart to localStorage
    localStorage.setItem('cart', JSON.stringify(cartItems));
  }, [cartItems]);

  const addToCart = (product) => {
    setCartItems(prev => {
      const existing = prev.find(item => item.product_id === product._id);
      if (existing) {
        return prev.map(item =>
          item.product_id === product._id
            ? { ...item, quantity: item.quantity + 1 }
            : item
        );
      }
      return [...prev, {
        product_id: product._id,
        name: product.name,
        price: product.price,
        unit: product.unit || 'kg',
        quantity: 1,
        category: product.category,
        is_regular: product.is_regular
      }];
    });
    setIsCartOpen(true);
  };

  const updateQuantity = (productId, delta) => {
    setCartItems(prev => {
      const newCart = prev.map(item =>
        item.product_id === productId
          ? { ...item, quantity: Math.max(1, item.quantity + delta) }
          : item
      ).filter(item => item.quantity > 0);
      return newCart;
    });
  };

  const removeFromCart = (productId) => {
    setCartItems(prev => prev.filter(item => item.product_id !== productId));
  };

  const clearCart = () => {
    setCartItems([]);
  };

  const cartCount = cartItems.reduce((sum, item) => sum + item.quantity, 0);
  const cartTotal = cartItems.reduce((sum, item) => sum + item.price * item.quantity, 0);

  const handleLogin = (userData, authToken) => {
    setUser(userData);
    setToken(authToken);
    localStorage.setItem('user', JSON.stringify(userData));
    localStorage.setItem('token', authToken);
  };

  const handleLogout = () => {
    setUser(null);
    setToken(null);
    localStorage.removeItem('user');
    localStorage.removeItem('token');
  };

  return (
    <Router>
      <div className="app">
        <Navbar
          cartCount={cartCount}
          onCartClick={() => setIsCartOpen(true)}
          user={user}
          onLogout={handleLogout}
        />
        <main className="main-content">
          <Routes>
            <Route path="/" element={<Home addToCart={addToCart} />} />
            <Route path="/category/:category" element={<Category addToCart={addToCart} />} />
            <Route
              path="/checkout"
              element={
                <Checkout
                  cartItems={cartItems}
                  cartTotal={cartTotal}
                  user={user}
                  token={token}
                  onLogin={handleLogin}
                  clearCart={clearCart}
                />
              }
            />
            <Route
              path="/dashboard"
              element={<Dashboard user={user} token={token} />}
            />
          </Routes>
        </main>
        <Footer />
        <CartDrawer
          isOpen={isCartOpen}
          onClose={() => setIsCartOpen(false)}
          cartItems={cartItems}
          updateQuantity={updateQuantity}
          removeFromCart={removeFromCart}
          cartTotal={cartTotal}
        />
      </div>
    </Router>
  );
}

export default App;
